"Pour les voyages terminés ({0}), les grandes photos déjà envoyées sur le serveur sont retirées de ce téléphone. Les vignettes restent : la grille et le film s’affichent toujours, et la grande photo revient du serveur, en version allégée, quand tu l’ouvres (il faut du réseau). Les photos pas encore envoyées ne sont jamais touchées.":"Biten seyahatlerde ({0}) sunucuya zaten gönderilmiş büyük fotoğraflar bu telefondan kaldırılır. Küçük resimler kalır: ızgara ve film görünmeye devam eder, büyük fotoğraf açtığında sunucudan hafif sürümüyle geri gelir (bağlantı gerekir). Henüz gönderilmemiş fotoğraflara asla dokunulmaz.",
"Retirer de ce téléphone les grandes photos des voyages terminés déjà sur le serveur ? Les vignettes restent, et chaque grande photo revient quand tu l’ouvres.":"Biten seyahatlerin sunucuda olan büyük fotoğrafları bu telefondan kaldırılsın mı? Küçük resimler kalır ve her büyük fotoğraf açtığında geri gelir.",
"🧹 {0} / {1}…":"🧹 {0} / {1}…",
"✅ {0} grande(s) photo(s) retirée(s) de ce téléphone · {1} Mo libérés.":"✅ Bu telefondan {0} büyük fotoğraf kaldırıldı · {1} MB boşaldı.",
"Rien à libérer pour le moment (photos pas encore envoyées, ou déjà libérées).":"Şimdilik açılacak yer yok (fotoğraflar henüz gönderilmedi veya zaten kaldırıldı).",
"Ton ami scanne le code de son téléphone avec l’appareil photo.":"Arkadaşın, telefonuna uygun kodu kamerayla tarar.",
