"📦 Place photos de ce carnet pleine sur le serveur ({0} Go) : les photos restantes restent sur ce téléphone, rien n’est perdu.":"📦 Bu günlüğün sunucudaki fotoğraf alanı doldu ({0} GB): kalan fotoğraflar bu telefonda kalır, hiçbir şey kaybolmaz.",
"📦 Place photos de ce carnet pleine sur le serveur : les photos restantes restent sur ce téléphone, rien n’est perdu.":"📦 Bu günlüğün sunucudaki fotoğraf alanı doldu: kalan fotoğraflar bu telefonda kalır, hiçbir şey kaybolmaz.",
"📦 Le serveur photos est plein pour le moment : les photos restantes restent sur ce téléphone, rien n’est perdu.":"📦 Fotoğraf sunucusu şu an dolu: kalan fotoğraflar bu telefonda kalır, hiçbir şey kaybolmaz.",
