"Aucune notification pour l’instant.":"Henüz bildirim yok.",
"Les notifications des 30 derniers jours restent ici, sur ce téléphone.":"Son 30 günün bildirimleri burada, bu telefonda kalır.",
"Les notifications sont désactivées : active-les dans Plus → ⚙️ Réglages.":"Bildirimler kapalı: Daha fazla → ⚙️ Ayarlar’dan aç.",
"🗑 Tout effacer":"🗑 Tümünü sil",
"Effacer toutes les notifications de la cloche ?":"Zildeki tüm bildirimler silinsin mi?",
