"Une note sur Google Play aide d’autres voyageurs à trouver l’appli, et m’encourage à continuer à l’améliorer. Ça prend 30 secondes. Merci 🙏":"Google Play’de bir puan, diğer gezginlerin uygulamayı bulmasına yardım eder ve beni geliştirmeye devam etmeye teşvik eder. 30 saniye sürer. Teşekkürler 🙏",
