"Il n’y a encore rien à raconter : ajoute des souvenirs avec des photos et des lieux.":"Henüz anlatacak bir şey yok: fotoğraflı ve yerli anılar ekle.",
"Ta route est visible des abonnés":"Rotan takipçilere görünüyor",
"Ta route est cachée aux abonnés":"Rotan takipçilerden gizli",
"Touche pour la cacher":"Gizlemek için dokun",
"Touche pour la montrer sur leur carte":"Haritalarında göstermek için dokun",
"La route du voyage":"Seyahat rotası",
"Route visible des abonnés":"Rota takipçilere görünür",
"Route masquée aux abonnés":"Rota takipçilerden gizli",
"Montrer ta route aux abonnés de ce voyage ?\n\nIls verront sur une carte le trajet enregistré par le suivi et ta dernière position (précision ≈ 100 m), avec l’heure.\nTu peux arrêter quand tu veux : la carte disparaît chez eux à la synchro suivante.\nTes compagnons choisissent chacun pour eux.":"Rotan bu seyahatin takipçilerine gösterilsin mi?\n\nTakiple kaydedilen güzergâhı ve son konumunu (≈ 100 m hassasiyet) saatiyle birlikte haritada görecekler.\nİstediğin zaman durdurabilirsin: harita bir sonraki senkronizasyonda onlardan kaybolur.\nHer yol arkadaşı kendisi için karar verir.",
"Publier « {0} » pour des abonnés ?\n\nIls verront uniquement les souvenirs : photos, titres, lieux et récits. Le programme, les réservations, le budget et les documents restent privés.\nUn souvenir marqué « privé » n’est jamais publié.\nIls voient les photos en vignettes (taille réduite).\nTa position n’est jamais montrée, sauf si chaque voyageur l’active lui-même dans le suivi du voyage.\nIls pourront mettre des ❤️ et des commentaires.":"“{0}” takipçiler için yayımlansın mı?\n\nYalnızca anıları görürler: fotoğraflar, başlıklar, yerler ve anlatılar. Program, rezervasyonlar, bütçe ve belgeler gizli kalır.\n“Gizli” olarak işaretlenen bir anı asla yayımlanmaz.\nFotoğrafları küçük resim (küçültülmüş boyut) olarak görürler.\nHer yolcu seyahat takibinde kendisi açmadıkça konumun asla gösterilmez.\n❤️ ve yorum bırakabilirler.",
