"Pour partager un seul voyage, inutile : dans le voyage, touche Partager. Seul ce voyage est alors stocké sur le serveur, tes autres voyages restent sur ton téléphone.":"Tek bir seyahati paylaşmak için gerek yok: seyahatte Paylaş’a dokun. O zaman yalnızca o seyahat sunucuda saklanır, diğerleri telefonunda kalır.",
