"Créer un nouveau code pour « {0} » ?\n\nLe voyage, ses fiches et ses photos repartent sur le serveur sous ce nouveau code. Les autres téléphones doivent ensuite le rejoindre avec le nouveau code (Mes voyages → Rejoindre un voyage partagé).":"“{0}” için yeni bir kod oluşturulsun mu?\n\nSeyahat, kayıtları ve fotoğrafları bu yeni kodla sunucuya yeniden gönderilir. Ardından diğer telefonların yeni kodla katılması gerekir (Seyahatlerim → Paylaşılan bir seyahate katıl).",
"⚠️ Le voyage n’a pas pu être envoyé sous le nouveau code : {0}\nRéessaie avec « Tout renvoyer » quand la connexion est bonne.":"⚠️ Seyahat yeni kodla gönderilemedi: {0}\nBağlantı iyiyken “Hepsini yeniden gönder” ile tekrar dene.",
"✅ Voyage en ligne : le code peut être donné":"✅ Seyahat çevrimiçi: kod paylaşılabilir",
"Ce voyage avait déjà un code (effacé du serveur, par exemple) ? Colle-le ici pour le réutiliser : les autres téléphones le retrouveront.\nSinon laisse vide : un nouveau code sera créé.":"Bu seyahatin daha önce bir kodu var mıydı (örneğin sunucudan silinen)? Yeniden kullanmak için buraya yapıştır: diğer telefonlar onu yeniden bulur.\nYoksa boş bırak: yeni bir kod oluşturulur.",
"🗑 Supprimé du serveur : {0} fiche(s) et {1} photo(s).\nTes données restent sur ce téléphone.\n\nGarder le code sur ce téléphone ?\nOK = je garde le code : tu pourras tout renvoyer plus tard avec le même code (bouton « Tout renvoyer »).\nAnnuler = j’oublie ce code ici.":"🗑 Sunucudan silindi: {0} kayıt ve {1} fotoğraf.\nVerilerin bu telefonda kalır.\n\nKod bu telefonda tutulsun mu?\nTamam = kodu tut: daha sonra aynı kodla her şeyi yeniden gönderebilirsin (“Hepsini yeniden gönder” düğmesi).\nİptal = bu kodu burada unut.",
"Le code est gardé. Pour tout remettre sur le serveur : {0} → « Tout renvoyer ».":"Kod tutuldu. Her şeyi sunucuya geri koymak için: {0} → “Hepsini yeniden gönder”.",
"Mes voyages → le voyage → code":"Seyahatlerim → seyahat → kod",
"📤 Voyage ou photos non arrivés ?":"📤 Seyahat ya da fotoğraflar gelmedi mi?",
"Renvoie vers le serveur toutes les fiches et toutes les photos de ce téléphone, par exemple après une suppression sur le serveur. Rien n’est dupliqué.":"Bu telefondaki tüm kayıtları ve fotoğrafları sunucuya yeniden gönderir, örneğin sunucudan silmeden sonra. Hiçbir şey çoğaltılmaz.",
"📤 Tout renvoyer":"📤 Hepsini yeniden gönder",
