"👀 3 voyages de démo sont prêts (rien n’est partagé) :\n\n📍 En cours : on est au jour 7 — traceur, steps, tickets, courses, plafond, parts inégales.\n🧳 Préparation : le même Japon dans 6 mois, à organiser.\n🗺️ Passés / 🏁 Bilan : le voyage terminé avec ses photos, son album et ses comptes.\n\nPasse d’un onglet à l’autre en haut de l’écran. « Supprimer la démo » efface tout.":"👀 3 demo seyahat hazır (hiçbir şey paylaşılmaz):\n\n📍 Süren: 7. gündeyiz — takip, adımlar, fişler, alışveriş, günlük limit, eşit olmayan paylar.\n🧳 Hazırlık: 6 ay sonraki aynı Japonya seyahati, düzenlenecek.\n🗺️ Geçmiş / 🏁 Özet: fotoğrafları, albümü ve hesaplarıyla biten seyahat.\n\nEkranın üstündeki sekmeler arasında geçiş yap. “Demoyu sil” her şeyi siler.",
