"La projection prend le prix réel quand il est saisi, sinon l’estimation.\nPrix « par personne » : compté pour chaque voyageur concerné. Prix « global » : divisé entre les voyageurs concernés. Un trajet décoché pour quelqu’un (retour séparé) ne lui est pas compté. Dans chaque fiche, 💶 indique qui prend en charge (égal, une personne, montants) et qui a payé.\n{0}":"Öngörü, girildiyse gerçek fiyatı, yoksa tahmini kullanır.\n“Kişi başı” fiyatlar: ilgili her yolcu için sayılır. “Toplam” fiyatlar: ilgili yolcular arasında bölünür. Biri için işareti kaldırılmış bir yolculuk (ayrı dönüş) ona sayılmaz. Her kayıtta 💶, masrafı kimin üstlendiğini (eşit, bir kişi, tutarlar) ve kimin ödediğini gösterir.\n{0}",
