"Un voyage peut avoir son propre code : seuls ceux qui l’ont le voient (par ex. Claire voit 2 voyages, Alex 1 seul). Ton code principal ci-dessous partage le reste.":"Bir seyahatin kendi kodu olabilir: yalnızca ona sahip olanlar görür (örn. Claire 2 seyahat görür, Alex yalnızca 1). Aşağıdaki ana kodun geri kalanı paylaşır.",
